from lib import *
L = lambda *a, **k: lesson(10, "A0", *a, **k)
A = "adjective"
L(1, "Фрукти і слово an", "Назвати фрукти й правильно вибрати a чи an.",
 "Перед словом, що починається з голосного звука, замість a кажуть an: an apple, an orange, an egg. Так легше вимовити. Перед приголосним лишається a: a banana, a lemon.",
 [W("fruit", "/fruːt/", "noun", "фрукти", "I like fruit.", "Я люблю фрукти."),
  W("apple", "/ˈæpl/", "noun", "яблуко", "An apple, please.", "Яблуко, будь ласка."),
  W("banana", "/bəˈnɑːnə/", "noun", "банан", "I have a banana.", "У мене є банан."),
  W("orange", "/ˈɒrɪndʒ/", "noun", "апельсин", "An orange.", "Апельсин."),
  W("lemon", "/ˈlemən/", "noun", "лимон", "Tea with lemon.", "Чай із лимоном."),
  W("egg", "/eɡ/", "noun", "яйце", "An egg.", "Яйце."),
  W("an", "/ən/", "determiner", "один, одна (перед голосним звуком)", "An apple.", "Яблуко.")],
 [li("Is there a lift?", "Повторимо. Ліфта немає. Що відповісти?", ["No, there isn't.", "No, there aren't.", "No, it isn't lift."], "No, there isn't."),
  mt([("apple", "яблуко"), ("banana", "банан"), ("orange", "апельсин"), ("lemon", "лимон")], "Orange — і колір, і фрукт."),
  mc("Як правильно?", ["an apple", "a apple", "an banana"], "Apple починається з голосного, тому an."),
  mc("Як правильно?", ["a banana", "an banana", "a egg"], "Banana починається з приголосного — a. Egg — an egg."),
  fb("I'd like ___ orange juice, please.", ["an", "a", "are"], "Orange починається з голосного: an orange juice."),
  fb("Can I have ___ lemon?", ["a", "an", "is"], "Lemon — з приголосного: a lemon."),
  liu("Tea with lemon, please.", "Прослухайте. Що просить людина?", ["Чай із лимоном", "Чай із молоком", "Сік із лимоном"], "With lemon — з лимоном."),
  bs("У мене є яблуко й банан.", ["I", "have", "an", "apple", "and", "a", "banana"], ["egg"], "An apple, але a banana."),
  tr("Я люблю фрукти.", ["I like fruit", "I love fruit"], "I like fruit. Fruit тут без -s."),
  li("Would you like an apple or an orange?", "Ви хочете яблуко. Що відповісти?", ["An apple, please.", "A apple, please.", "Yes, I like."], "An apple, please.")])
L(2, "Овочі", "Назвати овочі та гарніри.",
 "Більшість назв овочів мають множину на -s: carrots, onions. Після o додають -es: potatoes, tomatoes. Rice і pasta множини не мають.",
 [W("vegetables", "/ˈvedʒtəblz/", "noun", "овочі", "I like vegetables.", "Я люблю овочі."),
  W("potato", "/pəˈteɪtəʊ/", "noun", "картопля, картоплина", "Chicken with potatoes.", "Курка з картоплею."),
  W("tomato", "/təˈmɑːtəʊ/", "noun", "помідор", "A tomato salad.", "Салат із помідорів."),
  W("onion", "/ˈʌnjən/", "noun", "цибуля, цибулина", "No onion, please.", "Без цибулі, будь ласка."),
  W("carrot", "/ˈkærət/", "noun", "морква, морквина", "Carrot soup.", "Морквяний суп."),
  W("rice", "/raɪs/", "noun", "рис", "Chicken with rice.", "Курка з рисом."),
  W("pasta", "/ˈpæstə/", "noun", "макарони, паста", "Pasta with cheese.", "Паста із сиром.")],
 [mc("Повторимо. Як правильно?", ["an egg", "a egg", "an lemon"], "Egg — з голосного: an egg."),
  mt([("potato", "картопля"), ("tomato", "помідор"), ("onion", "цибуля"), ("carrot", "морква")], "Чотири овочі для супу."),
  mt([("rice", "рис"), ("pasta", "макарони"), ("vegetables", "овочі"), ("fruit", "фрукти")], "Rice і pasta — гарніри."),
  liu("Chicken with rice, please.", "Прослухайте. Що замовляє людина?", ["Курку з рисом", "Курку з картоплею", "Рис з овочами"], "With rice — з рисом."),
  mc("Як сказати «три помідори»?", ["three tomatoes", "three tomatos", "three tomato"], "Після o — -es: tomatoes."),
  fb("No ___, please. I don't like it.", ["onion", "an", "like"], "No onion — без цибулі."),
  liu("Soup with potatoes and carrots.", "Прослухайте. З чим суп?", ["З картоплею й морквою", "З картоплею й цибулею", "З рисом і морквою"], "Potatoes and carrots."),
  bs("Я люблю овочі.", ["I", "like", "vegetables"], ["fruit", "an"], "I like vegetables."),
  tr("Паста із сиром, будь ласка.", ["Pasta with cheese, please"], "Pasta with cheese, please."),
  li("Rice or potatoes?", "Ви хочете картоплю. Що відповісти?", ["Potatoes, please.", "Yes, please.", "A potatoes."], "Potatoes, please.")])
L(3, "М'ясо, риба і що я їм", "Сказати, що ви їсте й п'єте, а чого ні.",
 "I eat… — «я їм…», I drink… — «я п'ю…». Заперечення таке саме, як із like: I don't eat meat. I don't drink coffee. I'm vegetarian — «я вегетаріанець».",
 [W("eat", "/iːt/", "verb", "їсти", "I eat fish.", "Я їм рибу."),
  W("drink", "/drɪŋk/", "verb", "пити", "I drink tea.", "Я п'ю чай."),
  W("meat", "/miːt/", "noun", "м'ясо", "I don't eat meat.", "Я не їм м'яса."),
  W("fish", "/fɪʃ/", "noun", "риба", "Fish with rice.", "Риба з рисом."),
  W("butter", "/ˈbʌtə/", "noun", "вершкове масло", "Bread and butter.", "Хліб із маслом."),
  W("salt", "/sɔːlt/", "noun", "сіль", "Can I have the salt?", "Можна мені сіль?"),
  W("pepper", "/ˈpepə/", "noun", "перець", "Salt and pepper.", "Сіль і перець."),
  W("vegetarian", "/ˌvedʒəˈteəriən/", A, "вегетаріанський; вегетаріанець", "I'm vegetarian.", "Я вегетаріанець.")],
 [fb("Chicken with ___, please.", ["rice", "an", "eat"], "Chicken with rice.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("eat", "їсти"), ("drink", "пити"), ("meat", "м'ясо"), ("fish", "риба")], "Meat (м'ясо) і meet (зустріти) звучать однаково."),
  mt([("butter", "масло"), ("salt", "сіль"), ("pepper", "перець"), ("bread", "хліб")], "Те, що стоїть на столі."),
  liu("I don't eat meat.", "Прослухайте. Що каже людина?", ["Я не їм м'яса", "Я не їм риби", "Я їм м'ясо"], "I don't eat — я не їм."),
  fb("I ___ drink coffee in the evening.", ["don't", "not", "am not"], "I don't drink."),
  fb("I ___ fish, but I don't eat meat.", ["eat", "drink", "am"], "Рибу їдять — eat."),
  liu("Can I have the salt, please?", "Прослухайте. Що просить людина?", ["Сіль", "Перець", "Масло"], "Salt — сіль."),
  bs("Я не п'ю каву.", ["I", "don't", "drink", "coffee"], ["eat", "not"], "I don't drink coffee."),
  tr("Я вегетаріанець.", ["I'm vegetarian", "I am vegetarian", "I'm a vegetarian", "I am a vegetarian"], "I'm vegetarian."),
  li("Would you like the chicken or the fish?", "Ви не їсте м'яса. Що відповісти?", ["The fish, please. I don't eat meat.", "The chicken, please. I don't eat meat.", "I don't fish."], "Курка — це м'ясо, тому The fish, please.")])
L(4, "Я голодний", "Сказати, що ви голодні чи хочете пити, і попросити ще.",
 "I'm hungry — «я голодний», I'm thirsty — «я хочу пити». Some — «трохи, кілька»: Can I have some water? Коли наїлися — I'm full. Про смачну їжу — It's delicious.",
 [W("hungry", "/ˈhʌŋɡri/", A, "голодний", "I'm hungry.", "Я голодний."),
  W("thirsty", "/ˈθɜːsti/", A, "спраглий", "I'm thirsty.", "Я хочу пити."),
  W("full", "/fʊl/", A, "ситий; повний", "I'm full, thanks.", "Я ситий, дякую."),
  W("some", "/sʌm/", "determiner", "трохи, кілька", "Some water, please.", "Трохи води, будь ласка."),
  W("more", "/mɔː/", "determiner", "ще, більше", "Some more bread?", "Ще хліба?"),
  W("delicious", "/dɪˈlɪʃəs/", A, "дуже смачний", "It's delicious!", "Це дуже смачно!"),
  W("want", "/wɒnt/", "verb", "хотіти", "I want a sandwich.", "Я хочу сендвіч.")],
 [fb("I ___ eat meat. I'm vegetarian.", ["don't", "not", "am"], "I don't eat meat.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("hungry", "голодний"), ("thirsty", "спраглий"), ("full", "ситий"), ("delicious", "дуже смачний")], "Hungry — хочу їсти, thirsty — хочу пити."),
  mt([("some", "трохи"), ("more", "ще"), ("want", "хотіти"), ("very", "дуже")], "Some more — «ще трохи»."),
  liu("I'm very thirsty.", "Прослухайте. Чого хоче людина?", ["Пити", "Їсти", "Спати"], "Thirsty — хочу пити."),
  mc("Ви хочете їсти. Що сказати?", ["I'm hungry.", "I'm full.", "I'm thirsty."], "I'm hungry."),
  fb("Can I have ___ water, please?", ["some", "an", "are"], "Some water — трохи води."),
  liu("Would you like some more soup?", "Прослухайте. Що вам пропонують?", ["Ще супу", "Ще хліба", "Рахунок"], "Some more soup — ще супу."),
  bs("Це дуже смачно!", ["It's", "delicious"], ["full", "some"], "It's delicious!"),
  tr("Я голодний.", ["I'm hungry", "I am hungry"], "I'm hungry."),
  li("Would you like some more?", "Ви наїлися. Що відповісти?", ["No, thanks. I'm full.", "No, thanks. I'm hungry.", "Yes, I'm full."], "No, thanks. I'm full.")])
L(5, "Що я їм на сніданок", "Розповісти, що ви зазвичай їсте вранці, вдень і ввечері.",
 "For breakfast — «на сніданок», for lunch — «на обід», for dinner — «на вечерю». Про їжу часто кажуть have: I have toast for breakfast. Usually — «зазвичай», стоїть перед дієсловом: I usually have coffee.",
 [W("for", "/fɔː/", "preposition", "на, для", "For breakfast.", "На сніданок."),
  W("usually", "/ˈjuːʒuəli/", "adverb", "зазвичай", "I usually have tea.", "Я зазвичай п'ю чай."),
  W("toast", "/təʊst/", "noun", "тост, підсмажений хліб", "Toast with butter.", "Тост із маслом."),
  W("yoghurt", "/ˈjɒɡət/", "noun", "йогурт", "Yoghurt with fruit.", "Йогурт із фруктами."),
  W("pizza", "/ˈpiːtsə/", "noun", "піца", "I love pizza.", "Я обожнюю піцу."),
  W("wine", "/waɪn/", "noun", "вино", "Red wine, please.", "Червоного вина, будь ласка."),
  W("beer", "/bɪə/", "noun", "пиво", "A beer, please.", "Пиво, будь ласка.")],
 [mc("Повторимо. Ви наїлися. Що сказати?", ["I'm full.", "I'm hungry.", "I'm thirsty."], "I'm full."),
  mt([("toast", "тост"), ("yoghurt", "йогурт"), ("pizza", "піца"), ("usually", "зазвичай")], "Toast і yoghurt — типовий сніданок."),
  mt([("wine", "вино"), ("beer", "пиво"), ("juice", "сік"), ("water", "вода")], "Напої."),
  liu("For breakfast I have toast and coffee.", "Прослухайте. Що людина їсть на сніданок?", ["Тост і каву", "Тост і чай", "Йогурт і каву"], "Toast and coffee."),
  fb("I have a sandwich ___ lunch.", ["for", "on", "in"], "For lunch — на обід."),
  fb("I ___ have dinner at seven.", ["usually", "some", "for"], "I usually have dinner — зазвичай я вечеряю."),
  liu("A glass of red wine, please.", "Прослухайте. Що замовляє людина?", ["Червоне вино", "Біле вино", "Пиво"], "Red wine — червоне вино. A glass of — «келих»."),
  bs("На сніданок я їм йогурт.", ["I", "have", "yoghurt", "for", "breakfast"], ["eat", "at"], "I have yoghurt for breakfast."),
  tr("Я обожнюю піцу.", ["I love pizza"], "I love pizza."),
  li("What do you usually have for breakfast?", "Ви зазвичай їсте яйця й тост. Що відповісти?", ["I usually have eggs and toast.", "I usually eggs and toast.", "I'm usually eggs."], "I usually have eggs and toast.")])
L(6, "Повторення: їжа й напої", "Розповісти про свої смаки й попросити їжу за столом.",
 "Нових слів немає. Повторюємо a і an, I like і I don't eat, I'm hungry, some і more, for breakfast.",
 [],
 [mc("Як правильно?", ["an orange", "a orange", "an tomato"], "Orange — з голосного: an orange."),
  fb("I don't ___ meat, but I eat fish.", ["eat", "drink", "am"], "I don't eat meat."),
  li("Would you like some more pasta?", "Ви хочете ще. Що відповісти?", ["Yes, please. It's delicious!", "No, please. It's delicious!", "Yes, I'm full."], "Yes, please. It's delicious!"),
  tr("Можна мені трохи води?", ["Can I have some water", "Can I have some water, please"], "Can I have some water?"),
  liu("For lunch I usually have soup and a sandwich.", "Прослухайте. Що людина їсть на обід?", ["Суп і сендвіч", "Салат і сендвіч", "Суп і піцу"], "Soup and a sandwich."),
  bs("Я не п'ю пива.", ["I", "don't", "drink", "beer"], ["eat", "wine"], "I don't drink beer."),
  mc("Як сказати «дві картоплини»?", ["two potatoes", "two potatos", "two potato"], "Potatoes — з -es."),
  fb("I'm ___. Can I have a sandwich?", ["hungry", "thirsty", "full"], "Сендвіч просять, коли голодні."),
  tr("Я люблю овочі.", ["I like vegetables", "I love vegetables"], "I like vegetables."),
  li("What do you have for breakfast?", "Ви їсте йогурт із фруктами. Що відповісти?", ["I have yoghurt with fruit.", "I'm yoghurt with fruit.", "I have breakfast for yoghurt."], "I have yoghurt with fruit.")],
 review=True)
